function publicRiskView(value) {
  const complete = value?.coverage === 1 && typeof value.score === 'number'
    && Number.isFinite(value.score) && value.score >= 0 && value.score <= 100
    && ['bajo','medio','alto'].includes(value.level);
  return complete ? value : { level: 'desconocido', score: null, coverage: null };
}
function publicVerdictView(snapshot, language, fallback) {
  return typeof snapshot?.verdict_es === 'string' && typeof snapshot?.verdict_en === 'string'
    ? snapshot[language === 'en' ? 'verdict_en' : 'verdict_es'] : fallback;
}
